using ContosoUniversity;
using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    private static IQueryable<int> CreateSource(int count)
    {
        return Enumerable.Range(1, count).AsQueryable();
    }

    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

        Assert.Equal(3, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(4, result.TotalPages);
        Assert.Equal(new[] { 1, 2, 3 }, result);
    }

    [Fact]
    public void Create_MiddlePage_ReturnsCorrectItems()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

        Assert.Equal(3, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(new[] { 4, 5, 6 }, result);
    }

    [Fact]
    public void Create_LastPage_ReturnsCorrectItems()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 4, pageSize: 3);

        Assert.Equal(1, result.Count);
        Assert.Equal(4, result.PageIndex);
        Assert.Equal(new[] { 10 }, result);
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 4, pageSize: 3);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnFirstPage_ReturnsTrue()
    {
        var source = CreateSource(10);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

        Assert.True(result.HasNextPage);
    }

    [Theory]
    [InlineData(9, 3, 3)]
    [InlineData(10, 3, 4)]
    public void TotalPages_CalculatesCorrectly(int itemCount, int pageSize, int expectedTotalPages)
    {
        var source = CreateSource(itemCount);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: pageSize);

        Assert.Equal(expectedTotalPages, result.TotalPages);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

        Assert.Empty(result);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(0, result.TotalPages);
    }
}

