using ContosoUniversity.Controllers;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class HomeControllerTests
{
    [Fact]
    public void Index_ReturnsView()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void About_ReturnsViewWithEnrollmentDateGroups()
    {
        using var context = TestHelper.CreateContext();
        var date1 = new DateTime(2020, 9, 1);
        var date2 = new DateTime(2021, 9, 1);
        context.Students.AddRange(
            new Student { FirstMidName = "Alice", LastName = "A", EnrollmentDate = date1 },
            new Student { FirstMidName = "Bob", LastName = "B", EnrollmentDate = date1 },
            new Student { FirstMidName = "Carol", LastName = "C", EnrollmentDate = date2 }
        );
        context.SaveChanges();
        var controller = new HomeController(context);

        var result = controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Equal(2, model.Count);
        var groupWithTwo = Assert.Single(model, g => g.StudentCount == 2);
        Assert.Equal(2, groupWithTwo.StudentCount);
    }

    [Fact]
    public void About_EmptyDatabase_ReturnsEmptyList()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void Contact_ReturnsViewWithMessage()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.Contact();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("Your contact page.", viewResult.ViewData["Message"]);
    }

    [Fact]
    public void Contact_ReturnsViewResult()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.Contact();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.Error();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewWithMessage()
    {
        using var context = TestHelper.CreateContext();
        var controller = new HomeController(context);

        var result = controller.Unauthorized();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("You don't have permission to access this resource.", viewResult.ViewData["Message"]);
    }
}

