using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests
{
    private static StudentsController CreateController(SchoolContext context)
    {
        var controller = new StudentsController(context);
        controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(),
            Mock.Of<ITempDataProvider>());
        return controller;
    }

    private static void SeedThreeStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { LastName = "Williams", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "Adams", FirstMidName = "Bob", EnrollmentDate = new DateTime(2022, 1, 15) },
            new Student { LastName = "Smith", FirstMidName = "Charlie", EnrollmentDate = new DateTime(2024, 3, 10) }
        );
        context.SaveChanges();
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index(null, null, null, null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Equal(3, model!.Count);
        Assert.Equal("Adams", model[0].LastName);
        Assert.Equal("Smith", model[1].LastName);
        Assert.Equal("Williams", model[2].LastName);
    }

    [Fact]
    public void Index_NameDesc_OrdersByLastNameDescending()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index("name_desc", null, null, null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Equal(3, model!.Count);
        Assert.Equal("Williams", model[0].LastName);
        Assert.Equal("Smith", model[1].LastName);
        Assert.Equal("Adams", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index("Date", null, null, null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Equal(3, model!.Count);
        Assert.Equal("Adams", model[0].LastName);    // 2022-01-15
        Assert.Equal("Williams", model[1].LastName);  // 2023-09-01
        Assert.Equal("Smith", model[2].LastName);      // 2024-03-10
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index("date_desc", null, null, null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Equal(3, model!.Count);
        Assert.Equal("Smith", model[0].LastName);      // 2024-03-10
        Assert.Equal("Williams", model[1].LastName);  // 2023-09-01
        Assert.Equal("Adams", model[2].LastName);      // 2022-01-15
    }

    [Fact]
    public void Index_SearchFilter_FiltersStudentsByLastName()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index(null, null, "Smith", null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Single(model!);
        Assert.Equal("Smith", model[0].LastName);
        Assert.Equal("Charlie", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchFilter_FiltersStudentsByFirstName()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index(null, null, "Alice", null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Single(model!);
        Assert.Equal("Williams", model[0].LastName);
        Assert.Equal("Alice", model[0].FirstMidName);
    }

    [Fact]
    public void Index_NewSearch_ResetsPageToOne()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index(null, null, "Smith", null) as ViewResult;

        Assert.Equal("Smith", result!.ViewData["CurrentFilter"]);
    }

    [Fact]
    public void Index_NullSearch_UsesCurrentFilter()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        var result = controller.Index(null, "Smith", null, null) as ViewResult;
        var model = result!.Model as PaginatedList<Student>;

        Assert.Equal("Smith", result.ViewData["CurrentFilter"]);
        Assert.Single(model!);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        using var context = TestHelper.CreateContext();
        SeedThreeStudents(context);
        var controller = CreateController(context);

        // Default sort (empty sortOrder) => NameSortParm = "name_desc", DateSortParm = "Date"
        var result = controller.Index(null, null, null, null) as ViewResult;
        Assert.Equal("name_desc", result!.ViewData["NameSortParm"]);
        Assert.Equal("Date", result.ViewData["DateSortParm"]);

        // sortOrder = "Date" => NameSortParm = "", DateSortParm = "date_desc"
        var result2 = controller.Index("Date", null, null, null) as ViewResult;
        Assert.Equal("", result2!.ViewData["NameSortParm"]);
        Assert.Equal("date_desc", result2.ViewData["DateSortParm"]);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { LastName = "Jones", FirstMidName = "Diana", EnrollmentDate = new DateTime(2023, 5, 1) };
        context.Students.Add(student);
        context.SaveChanges();
        var controller = CreateController(context);

        var result = controller.Details(student.ID) as ViewResult;
        var model = result!.Model as Student;

        Assert.Equal("Jones", model!.LastName);
        Assert.Equal("Diana", model.FirstMidName);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Details(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Create() as ViewResult;
        var model = result!.Model as Student;

        Assert.Equal(DateTime.Today, model!.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_SavesAndRedirects()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);
        var student = new Student
        {
            LastName = "Green",
            FirstMidName = "Emily",
            EnrollmentDate = new DateTime(2023, 8, 20)
        };

        var result = controller.Create(student);

        Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", ((RedirectToActionResult)result).ActionName);
        var saved = context.Students.Single(s => s.LastName == "Green");
        Assert.Equal("Emily", saved.FirstMidName);
        Assert.Equal(new DateTime(2023, 8, 20), saved.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);
        controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            LastName = "",
            FirstMidName = "Frank",
            EnrollmentDate = new DateTime(2023, 8, 20)
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        var model = result.Model as Student;
        Assert.Equal("Frank", model!.FirstMidName);
        Assert.Empty(context.Students.Where(s => s.FirstMidName == "Frank"));
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);
        var student = new Student
        {
            LastName = "Hall",
            FirstMidName = "Grace",
            EnrollmentDate = DateTime.MinValue
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        Assert.Contains(controller.ModelState["EnrollmentDate"]!.Errors,
            e => e.ErrorMessage.Contains("valid enrollment date"));
        Assert.Empty(context.Students.Where(s => s.LastName == "Hall"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { LastName = "King", FirstMidName = "Henry", EnrollmentDate = new DateTime(2023, 1, 10) };
        context.Students.Add(student);
        context.SaveChanges();
        var controller = CreateController(context);

        var result = controller.Edit(student.ID) as ViewResult;
        var model = result!.Model as Student;

        Assert.Equal("King", model!.LastName);
        Assert.Equal("Henry", model.FirstMidName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Edit(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFoundId_ReturnsNotFound()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_SavesAndRedirects()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { LastName = "Lee", FirstMidName = "Irene", EnrollmentDate = new DateTime(2023, 2, 15) };
        context.Students.Add(student);
        context.SaveChanges();
        context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        var controller = CreateController(context);

        var updated = new Student
        {
            ID = student.ID,
            LastName = "Lee-Updated",
            FirstMidName = "Irene",
            EnrollmentDate = new DateTime(2023, 6, 1)
        };

        var result = controller.Edit(updated);

        Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", ((RedirectToActionResult)result).ActionName);
        var saved = context.Students.Find(student.ID);
        Assert.Equal("Lee-Updated", saved!.LastName);
        Assert.Equal(new DateTime(2023, 6, 1), saved.EnrollmentDate);
    }

    [Fact]
    public void Edit_Post_InvalidDate_ReturnsViewWithError()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);
        var student = new Student
        {
            ID = 1,
            LastName = "Miller",
            FirstMidName = "Jack",
            EnrollmentDate = DateTime.MinValue
        };

        var result = controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        var model = result.Model as Student;
        Assert.Equal("Miller", model!.LastName);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { LastName = "Nelson", FirstMidName = "Karen", EnrollmentDate = new DateTime(2023, 4, 5) };
        context.Students.Add(student);
        context.SaveChanges();
        var controller = CreateController(context);

        var result = controller.Delete(student.ID) as ViewResult;
        var model = result!.Model as Student;

        Assert.Equal("Nelson", model!.LastName);
        Assert.Equal("Karen", model.FirstMidName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Delete(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFoundId_ReturnsNotFound()
    {
        using var context = TestHelper.CreateContext();
        var controller = CreateController(context);

        var result = controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteConfirmed_Success_RemovesAndRedirects()
    {
        using var context = TestHelper.CreateContext();
        var student = new Student { LastName = "Parker", FirstMidName = "Leo", EnrollmentDate = new DateTime(2023, 7, 20) };
        context.Students.Add(student);
        context.SaveChanges();
        var controller = CreateController(context);

        var result = controller.DeleteConfirmed(student.ID);

        Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", ((RedirectToActionResult)result).ActionName);
        Assert.Null(context.Students.Find(student.ID));
        Assert.Empty(context.Students.Where(s => s.LastName == "Parker"));
    }
}

