        mockEnv.Setup(e => e.ContentRootPath).Returns("/fake");
        var mockLogger = new Mock<ILogger<CoursesController>>();
        var controller = new CoursesController(context, mockEnv.Object, mockLogger.Object);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
        return controller;
    }

    private static Department SeedDepartment(SchoolContext context)
