using System;
using ContosoUniversity.Controllers;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests
{
    private static void DrainNotificationQueue()
    {
        var service = new NotificationService();
        while (service.ReceiveNotification() != null) { }
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
    {
        DrainNotificationQueue();
        using var context = TestHelper.CreateContext();
        var controller = new NotificationsController(context);

        var result = controller.GetNotifications();

        Assert.NotNull(result);
        var value = result.Value;
        Assert.NotNull(value);
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        Assert.True((bool)successProp!.GetValue(value)!);
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        DrainNotificationQueue();
        var service = new NotificationService();
        service.SendNotification("Student", "1", Models.EntityOperation.CREATE, "TestUser");
        service.SendNotification("Course", "2", Models.EntityOperation.UPDATE, "TestUser");

        using var context = TestHelper.CreateContext();
        var controller = new NotificationsController(context);

        var result = controller.GetNotifications();

        Assert.NotNull(result);
        var value = result.Value;
        Assert.NotNull(value);
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        Assert.True((bool)successProp!.GetValue(value)!);
        Assert.True((int)countProp!.GetValue(value)! > 0);
    }

    [Fact]
    public void MarkAsRead_Success_ReturnsSuccessJson()
    {
        using var context = TestHelper.CreateContext();
        var controller = new NotificationsController(context);

        var result = controller.MarkAsRead(1);

        Assert.NotNull(result);
        var value = result.Value;
        Assert.NotNull(value);
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        using var context = TestHelper.CreateContext();
        var controller = new NotificationsController(context);

        var result = controller.Index();

        Assert.IsType<ViewResult>(result);
    }
}

