using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            DrainQueue();
        }

        public void Dispose()
        {
            DrainQueue();
            _service.Dispose();
        }

        private void DrainQueue()
        {
            while (_service.ReceiveNotification() != null) { }
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesWithCorrectMessage()
        {
            _service.SendNotification("Course", "1", "Intro to CS", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Course 'Intro to CS' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Course", "42", null, EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("(ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            _service.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Admin", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _service.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsOperationString()
        {
            _service.SendNotification("Course", "1", "Test Course", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void SendNotification_SetsEntityTypeAndId()
        {
            _service.SendNotification("Course", "101", "Test Course", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("101", notification.EntityId);
        }

        [Fact]
        public void SendNotification_SetsIsReadFalse()
        {
            _service.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;

            _service.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.True((DateTime.Now - notification.CreatedAt).TotalSeconds < 5,
                "CreatedAt should be within 5 seconds of now");
            Assert.True(notification.CreatedAt >= before.AddSeconds(-1),
                "CreatedAt should not be before the test started");
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var notification = _service.ReceiveNotification();

            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_WithItems_ReturnsAndRemovesItem()
        {
            _service.SendNotification("Course", "1", "Test Course", EntityOperation.CREATE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        [Fact]
        public void GenerateMessage_Create_ContainsCreated()
        {
            _service.SendNotification("Course", "1", "Intro", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("has been created", notification.Message);
            Assert.Equal("New Course 'Intro' has been created", notification.Message);
        }

        [Fact]
        public void GenerateMessage_Update_ContainsUpdated()
        {
            _service.SendNotification("Course", "1", "Intro", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("has been updated", notification.Message);
            Assert.Equal("Course 'Intro' has been updated", notification.Message);
        }

        [Fact]
        public void GenerateMessage_Delete_ContainsDeleted()
        {
            _service.SendNotification("Course", "1", "Intro", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("has been deleted", notification.Message);
            Assert.Equal("Course 'Intro' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_ShortOverload_Works()
        {
            _service.SendNotification("Student", "99", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("99", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("Student (ID: 99) has been updated", notification.Message);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(1));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            using var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }
    }
}
